import java.io.BufferedReader;import java.io.InputStreamReader;import java.util.StringTokenizer;public class TestClass {public static void main(String[] args) throws Exception {BufferedReader br = new BufferedReader(new InputStreamReader(System.in));String line = br.readLine();if (line == null) return;int t = Integer.parseInt(line.trim());while (t-- > 0) {int n = Integer.parseInt(br.readLine().trim());StringTokenizer st = new StringTokenizer(br.readLine());long totalSum = 0;long minOdd = Long.MAX_VALUE;boolean hasOdd = false;for (int i = 0; i < n; i++) {long val = Long.parseLong(st.nextToken());totalSum += val;if (val % 2 != 0) {hasOdd = true;if (val < minOdd) {minOdd = val;}}}if (totalSum % 2 != 0) {System.out.println(totalSum);} else {if (!hasOdd) {System.out.println(0);} else {System.out.println(totalSum - minOdd);}}}}}